<script setup lang="ts">import {onMounted,computed} from 'vue';import {useResearch} from '../stores/research';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import InteractionPlot from '../components/InteractionPlot.vue';import RunSummary from '../components/RunSummary.vue';import CellMatrix from '../components/CellMatrix.vue';import RunTable from '../components/RunTable.vue';const lab=useResearch(),{error,perform}=useTask();const latest=computed(()=>lab.runs.find(r=>r.study_id===1&&r.status==='completed')||lab.runs.find(r=>r.status==='completed'));onMounted(()=>perform(lab.load));</script><template><PageHeading index="01" title="先读交互，再解释平均作用" text="完整平衡的温度×釉层试验，把处理格、因子和后续验证放在同一本记录里。"><RouterLink class="outline" to="/runs">建立分析记录 +</RouterLink></PageHeading><ErrorNotice :message="error" @retry="perform(lab.load)"/><section v-if="latest" class="overview-experiment"><InteractionPlot :run="latest"/><RunSummary :run="latest"/></section><div v-if="latest" class="overview-notes"><CellMatrix :cells="latest.result.cells||[]" :a="latest.result.a_levels||[]" :b="latest.result.b_levels||[]"/><aside class="lab-note"><p class="eyebrow">ANALYST NOTE / 01</p><h2>差异先规定，<br>结论再讨论。</h2><p>3温度×2釉层的全部简单效应共9项，作为同一家族统一Holm校正；不会只保留显著的一项。</p><p>交互有统计证据时，温度主效应只代表跨釉层平均，不能直接当成普遍升温规律。</p><RouterLink to="/plans">读取后续实验提案 ↗</RouterLink></aside></div><section class="run-directory"><div class="section-heading"><h2>分析记录与边界</h2><span>交互 / 加性对照 / 常量不可估</span></div><RunTable :runs="lab.runs.slice(0,5)"/></section></template>
